{"tool": "brick.build", "input": {"code": "script({
  title: "Endor-928: Ewok Classic Space Canopy Outpost & Timber-Wing Explorer",
  description: "A rich mash-up of late-1970s LEGO Classic Space (928 Galaxy Explorer, 926 Command Center, 920 Alpha-1 Rocket Base, 886 Space Buggy, and 918 Scout Ship) re-engineered by Ewok spacefarers from giant hollow Sequoia trees, woven timber, thatch, bamboo, and glowing amber tree-sap crystals.",
  palette: {
    bark: "reddish brown",
    darkBark: "dark brown",
    timber: "tan",
    darkTimber: "dark tan",
    foliage: "green",
    deepFoliage: "dark green",
    moss: "lime",
    amber: "trans yellow",
    sapFire: "trans red",
    spaceYellow: "yellow",
    hazardBlack: "black",
    stoneMix: { mix: ["light bluish grey", "dark bluish grey", "reddish brown"] },
    barkMix: { mix: ["reddish brown", "dark tan"] },
    canopyMix: { mix: ["green", "dark green"] }
  }
});

// Nominal footprint lookup [xStuds, stackingPlates, zStuds] at turn 0 for 100% overlap-free placement
const PART_DIMS = {
  "3005": [1, 3, 1], "3004": [2, 3, 1], "3622": [3, 3, 1], "3010": [4, 3, 1],
  "3009": [6, 3, 1], "3008": [8, 3, 1], "3003": [2, 3, 2], "3002": [3, 3, 2],
  "3001": [4, 3, 2], "2456": [6, 3, 2], "98283": [2, 3, 1], "30136": [2, 3, 1],
  "2877": [2, 3, 1], "3024": [1, 1, 1], "3023b": [2, 1, 1], "3623": [3, 1, 1],
  "3710": [4, 1, 1], "3666": [6, 1, 1], "3460": [8, 1, 1], "3022": [2, 1, 2],
  "3021": [3, 1, 2], "3020": [4, 1, 2], "3795": [6, 1, 2], "3034": [8, 1, 2],
  "3031": [4, 1, 4], "3032": [6, 1, 4], "51739": [4, 1, 3], "41769a": [2, 1, 4],
  "41770a": [2, 1, 4], "43722a": [2, 1, 3], "43723a": [2, 1, 3], "3070b": [1, 1, 1],
  "3069b": [2, 1, 1], "63864": [3, 1, 1], "2431": [4, 1, 1], "6636": [6, 1, 1],
  "3068b": [2, 1, 2], "87079": [4, 1, 2], "2412b": [2, 1, 1], "54200": [1, 2, 1],
  "85984": [2, 2, 1], "3040b": [1, 3, 2], "3039": [2, 3, 2], "3038": [3, 3, 2],
  "3037": [4, 3, 2], "3665a": [1, 3, 2], "3660b": [2, 3, 2], "3298": [2, 3, 3],
  "3747b": [2, 3, 3], "11477": [1, 3, 2], "15068": [2, 3, 2], "50950": [1, 3, 3],
  "61678": [1, 3, 4], "3062b": [1, 3, 1], "3941": [2, 3, 2], "87081": [4, 3, 4],
  "6141": [1, 1, 1], "4032b": [2, 1, 2], "98138": [1, 1, 1], "14769": [2, 1, 2],
  "4589": [1, 3, 1], "3942c": [2, 6, 2], "3943b": [4, 6, 4], "4740": [2, 1, 2],
  "3960": [4, 2, 4], "35394": [4, 2, 4], "3961": [8, 3, 8], "50990b": [12, 3, 12],
  "3957a": [1, 12, 1], "4599b": [1, 3, 1], "2489": [2, 5, 2], "4424": [4, 6, 4],
  "3939": [6, 3, 3], "2437": [4, 4, 3], "6238a": [4, 3, 4], "4079": [2, 6, 2],
  "3829c01": [2, 6, 1], "4600": [4, 5, 2], "4345b": [2, 6, 3], "4588": [2, 3, 2],
  "3940b": [2, 6, 2], "2340": [1, 9, 5], "3587": [2, 11, 5], "30385": [1, 5, 1],
  "30176": [1, 3, 1], "32607": [1, 1, 1], "24866": [1, 1, 1], "2423": [3, 1, 4],
  "2417": [5, 1, 6], "2435": [3, 12, 3], "3470": [4, 18, 4], "3659": [4, 3, 1],
  "6182": [4, 6, 1], "3307": [6, 6, 1]
};

const occupied = new Set();
const key = (x, y, z) => `${x},${y},${z}`;

function reserveBox(x, y, z, w, h, d, pad = 0) {
  for (let ix = x - pad; ix < x + w + pad; ix++) {
    for (let iy = y; iy < y + h; iy++) {
      for (let iz = z - pad; iz < z + d + pad; iz++) {
        occupied.add(key(ix, iy, iz));
      }
    }
  }
}

function p(part, at, colour, turn = 0, extra = {}) {
  const dims = PART_DIMS[part] || [2, 3, 2];
  const [x, y, z] = at;
  const w = (turn === 90 || turn === 270) ? dims[2] : dims[0];
  const h = dims[1];
  const d = (turn === 90 || turn === 270) ? dims[0] : dims[2];
  // Extra reach padding for foliage/trees
  const pad = (part === "3470" || part === "2435") ? 1 : 0;
  for (let ix = x - pad; ix < x + w + pad; ix++) {
    for (let iy = y; iy < y + h; iy++) {
      for (let iz = z - pad; iz < z + d + pad; iz++) {
        if (occupied.has(key(ix, iy, iz))) return null;
      }
    }
  }
  reserveBox(x, y, z, w, h, d, pad);
  return place({ part, at: [x, y, z], colour, turn, ...extra });
}

// Helper for a glowing Ewok Amber-Sap Space Beacon (barrel + sap cone + radar dish)
function sapBeacon(x, y, z) {
  return [
    p("2489", [x, y, z], "reddish brown"),
    p("4740", [x, y + 5, z], "trans yellow"),
    p("4589", [x, y + 6, z], "trans red"),
    p("4589", [x + 1, y + 6, z + 1], "trans yellow"),
    p("32607", [x, y + 5, z + 1], "green"),
    p("32607", [x + 1, y + 5, z], "lime")
  ];
}

// Helper for gnarled redwood root spurs gripping the forest floor
function rootSpur(x, z, dirX, dirZ, steps = 5) {
  const ops = [];
  for (let i = 0; i < steps; i++) {
    const rx = x + dirX * i;
    const rz = z + dirZ * i;
    const h = Math.max(2, (steps - i) * 2);
    ops.push(
      box({
        at: [rx, 0, rz],
        size: [2, h, 2],
        colour: i % 2 === 0 ? "reddish brown" : "dark tan",
        interior: "solid"
      })
    );
    const turn = dirZ < 0 ? 0 : dirZ > 0 ? 180 : dirX < 0 ? 90 : 270;
    ops.push(p("11477", [rx, h, rz], i % 2 === 0 ? "reddish brown" : "dark brown", turn));
    if (i === steps - 1) {
      ops.push(p("32607", [rx, h, rz + (dirZ === 0 ? 1 : 0)], "green"));
      ops.push(p("24866", [rx + (dirX === 0 ? 1 : 0), h, rz], "yellow"));
    }
  }
  return ops;
}

// ============================================================================
// SECTION 1: CENTERPIECE REDWOOD STUMP LANDING PAD & UNDER-PAD SAP CAVERN
// ============================================================================
const s1Ops = [];

// Local mossy forest-floor footing under the giant stump
s1Ops.push(
  floor({ at: [-16, 0, -22], size: [32, 34], layers: 2, colour: "dark green", top: "tile" }),
  floor({ at: [-18, 0, -16], size: [36, 24], layers: 1, colour: "green", top: "tile" })
);

// 8 Splayed Redwood Root Buttresses radiating from the hollow stump
s1Ops.push(
  ...rootSpur(-15, -18, -1, -1, 4),
  ...rootSpur(13, -18, 1, -1, 4),
  ...rootSpur(-15, 8, -1, 1, 4),
  ...rootSpur(13, 8, 1, 1, 4),
  ...rootSpur(-16, -6, -1, 0, 4),
  ...rootSpur(14, -6, 1, 0, 4),
  ...rootSpur(-8, -21, 0, -1, 3),
  ...rootSpur(6, -21, 0, -1, 3)
);

// Hollow Giant Redwood Stump (Y: 2..14) housing the Under-Pad Sap Refueling Cavern
s1Ops.push(
  room({
    at: [-13, 2, -19],
    size: [26, 12, 30],
    colour: "reddish brown",
    texture: "log",
    quoins: "dark tan",
    floor: "dark bluish grey",
    openings: [
      { side: "front", at: 8, width: 10, y: 0, height: 10, fill: "none" },
      { side: "back", at: 8, width: 10, y: 0, height: 10, fill: "none" },
      { side: "left", at: 10, width: 8, y: 0, height: 9, fill: "none" },
      { side: "right", at: 10, width: 8, y: 0, height: 9, fill: "none" }
    ]
  })
);

// Fluted outer bark ribs & mossy ledges around the stump perimeter
for (let z = -18; z <= 8; z += 4) {
  s1Ops.push(
    box({ at: [-14, 2, z], size: [1, 11, 2], colour: "dark tan", texture: "log" }),
    box({ at: [13, 2, z], size: [1, 11, 2], colour: "dark tan", texture: "log" }),
    p("11477", [-14, 13, z], "reddish brown", 90),
    p("11477", [13, 13, z], "reddish brown", 270),
    p("32607", [-14, 13, z + 1], "green"),
    p("32607", [13, 13, z + 1], "lime")
  );
}

// Interior Under-Pad Sap-Refueling Cavern Details (Y: 3..13)
// Timber archway headers at front (-Z) and back (+Z)
s1Ops.push(
  p("3307", [-3, 10, -19], "dark tan", 0),
  p("3307", [-3, 10, 10], "dark tan", 0)
);

// Glowing Amber-Sap Fuel Vats & Classic Space Cavern Consoles inside the stump
for (const sx of [-9, 7]) {
  for (const sz of [-12, 0]) {
    s1Ops.push(
      p("2489", [sx, 3, sz], "reddish brown"),
      p("4740", [sx, 8, sz], "trans yellow"),
      p("30385", [sx, 9, sz], "yellow"),
      p("4599b", [sx + 1, 9, sz + 1], "pearl gold")
    );
  }
}
// Cavern technician seats & Classic Space steering/computer stands
s1Ops.push(
  p("4079", [-4, 3, -8], "yellow", 0),
  p("3829c01", [-4, 3, -10], "light bluish grey", 0),
  p("85984", [-2, 3, -10], "yellow", 0),
  p("4079", [2, 3, 2], "red", 180),
  p("3829c01", [2, 3, 4], "light bluish grey", 180),
  p("85984", [0, 3, 4], "tan", 180)
);

// Internal 2x2 timber pillars supporting the landing deck
for (const px of [-10, 8]) {
  for (const pz of [-15, 5]) {
    reserveBox(px, 3, pz, 2, 11, 2);
    s1Ops.push(column({ at: [px, 3, pz], diameter: 2, height: 11, colour: "reddish brown" }));
  }
}

// Elevated Timber Landing Pad Deck (Y: 14..16) - Homage to 1979 Classic Space Landing Plate
s1Ops.push(
  floor({ at: [-14, 14, -20], size: [28, 32], layers: 2, colour: "dark tan", top: "tile" }),
  floor({ at: [-12, 16, -18], size: [24, 28], layers: 1, colour: "tan", top: "tile" })
);

// Classic Space 1979 Yellow Landing Cross, Hazard Chevron & Timber Plank Inlays at Y: 17
for (let x = -8; x <= 6; x += 2) {
  s1Ops.push(p("3069b", [x, 17, -5], "yellow", 0));
  s1Ops.push(p("3069b", [x, 17, -4], "yellow", 0));
}
for (let z = -14; z <= 4; z += 2) {
  if (z !== -5 && z !== -4) {
    s1Ops.push(p("3069b", [-1, 17, z], "yellow", 0));
  }
}
// Front & Back Yellow/Black Classic Space Hazard Threshold Stripes
for (let x = -10; x <= 8; x += 2) {
  const col = (Math.abs(x / 2) % 2 === 0) ? "yellow" : "black";
  s1Ops.push(
    p("3069b", [x, 17, -18], col, 0),
    p("3069b", [x, 17, 9], col, 0),
    p("2412b", [x, 17, -17], "reddish brown", 0),
    p("2412b", [x, 17, 8], "reddish brown", 0)
  );
}
// Side Wooden Grating & Amber Runway Lights along the Landing Pad Edges
for (let z = -16; z <= 6; z += 3) {
  s1Ops.push(
    p("2412b", [-12, 17, z], "reddish brown", 90),
    p("2412b", [11, 17, z], "reddish brown", 90),
    p("98138", [-13, 16, z], "trans yellow", 0),
    p("98138", [12, 16, z], "trans yellow", 0),
    p("32607", [-13, 16, z + 1], "green", 0),
    p("32607", [12, 16, z + 1], "green", 0)
  );
}

// 4 Corner Ewok Torch-Radar Beacons on the Landing Deck Corners
s1Ops.push(
  ...sapBeacon(-14, 16, -20),
  ...sapBeacon(12, 16, -20),
  ...sapBeacon(-14, 16, 10),
  ...sapBeacon(12, 16, 10)
);

// Forest Floor Scatter & Foliage Clusters around the Stump Base
for (let x = -16; x <= 14; x += 3) {
  s1Ops.push(
    p("32607", [x, 2, -21], "green"),
    p("24866", [x + 1, 2, -21], "yellow"),
    p("32607", [x, 2, 11], "lime"),
    p("54200", [x + 1, 2, 11], "reddish brown", (x * 90) & 270)
  );
}

section("Stump Landing Pad and Sap Cavern", s1Ops);

// ============================================================================
// SECTION 2: THE "LL-928 TIMBER-WING" EWOK GALAXY EXPLORER (Y: 17..40)
// ============================================================================
const s2Ops = [];

// 4 Timber & Amber Landing Skids supporting the 928 Explorer at Y: 17..20
for (const [sx, sz] of [[-7, -12], [5, -12], [-9, 2], [7, 2]]) {
  s2Ops.push(
    p("3001", [sx, 17, sz], "reddish brown", 90),
    p("3660b", [sx, 17, sz - 2], "dark tan", 0),
    p("3660b", [sx, 17, sz + 4], "dark tan", 180)
  );
}

// Stepped Delta Wing & Fuselage Lower Hull Platform (Y: 20..22)
// Faithful 928 Galaxy Explorer silhouette: narrow nose (-Z) widening to 26-stud delta wing (+Z)
s2Ops.push(
  // Central fuselage keel (Z: -21..10)
  floor({ at: [-3, 20, -21], size: [6, 31], layers: 2, colour: "reddish brown", top: "tile" }),
  // Forward cockpit cheek plates (Z: -17..-8)
  floor({ at: [-5, 20, -17], size: [10, 9], layers: 2, colour: "reddish brown", top: "tile" }),
  // Inner delta wing tier (X: -8..8, Z: -10..8)
  floor({ at: [-8, 20, -10], size: [16, 18], layers: 2, colour: "tan", top: "tile" }),
  // Mid delta wing tier (X: -11..11, Z: -5..8)
  floor({ at: [-11, 20, -5], size: [22, 13], layers: 2, colour: "dark tan", top: "tile" }),
  // Outer delta wing tips (X: -13..13, Z: 0..8)
  floor({ at: [-13, 20, 0], size: [26, 8], layers: 2, colour: "tan", top: "tile" })
);

// Sculpted Wing Leading Edges using Wedge Plates, Curved Slopes & Planking Tiles at Y: 22
// Left (-X) & Right (+X) stepped delta wing leading edges
const wingSteps = [
  { lx: -5, rx: 3, z: -17, lPart: "43723a", rPart: "43722a", col: "reddish brown" },
  { lx: -7, rx: 5, z: -13, lPart: "41770a", rPart: "41769a", col: "reddish brown" },
  { lx: -9, rx: 7, z: -9, lPart: "41770a", rPart: "41769a", col: "tan" },
  { lx: -11, rx: 9, z: -5, lPart: "41770a", rPart: "41769a", col: "dark tan" },
  { lx: -13, rx: 11, z: -1, lPart: "41770a", rPart: "41769a", col: "tan" }
];
for (const ws of wingSteps) {
  s2Ops.push(
    p(ws.lPart, [ws.lx, 22, ws.z], ws.col, 0),
    p(ws.rPart, [ws.rx, 22, ws.z], ws.col, 0)
  );
}

// Wing Surface Timber Ribs, Woven Slat Grilles & Leaf-Camouflage Accents (Y: 22)
for (let z = -8; z <= 6; z += 2) {
  s2Ops.push(
    p("2412b", [-7, 22, z], "reddish brown", 0),
    p("2412b", [5, 22, z], "reddish brown", 0),
    p("3069b", [-7, 22, z + 1], "dark tan", 0),
    p("3069b", [5, 22, z + 1], "dark tan", 0)
  );
  if (z >= -4) {
    s2Ops.push(
      p("11477", [-9, 22, z], "reddish brown", 90),
      p("11477", [7, 22, z], "reddish brown", 270),
      p("2412b", [-10, 22, z], "yellow", 90),
      p("2412b", [9, 22, z], "yellow", 90),
      p("32607", [-8, 22, z + 1], "green", 0),
      p("32607", [7, 22, z + 1], "green", 0)
    );
  }
}

// Classic Space "LL-928" Tribal Stripe & Star-Emblem on Upper Wings (Y: 22..23)
s2Ops.push(
  p("2431", [-11, 22, 5], "yellow", 0),
  p("2431", [7, 22, 5], "yellow", 0),
  p("2431", [-11, 22, 6], "reddish brown", 0),
  p("2431", [7, 22, 6], "reddish brown", 0),
  p("4740", [-10, 23, 3], "trans yellow", 0),
  p("4740", [8, 23, 3], "trans yellow", 0),
  p("98138", [-9, 23, 2], "red", 0),
  p("98138", [8, 23, 2], "green", 0)
);

// Wingtip Hollow-Barrel Thruster Pods & Forward Bamboo Sensor Spears (X: -14..-12 and X: 12..14)
for (const [wx, navCol, turnSide] of [[-13, "trans red", 90], [11, "green", 270]]) {
  s2Ops.push(
    p("2489", [wx, 22, 1], "reddish brown", 0),
    p("2489", [wx, 22, 4], "dark brown", 0),
    p("4588", [wx, 22, 6], "tan", 0),
    p("4589", [wx, 22, 8], "trans yellow", 0),
    p("4589", [wx + 1, 22, 8], "trans red", 0),
    p("4599b", [wx, 22, -1], "pearl gold", 0),
    p("4589", [wx + 1, 22, -1], navCol, 0),
    p("30176", [wx, 25, 0], "green", 0),
    p("3957a", [wx + 1, 25, 0], "tan", 0),
    p("11477", [wx, 27, 2], "tan", 0),
    p("11477", [wx, 27, 4], "reddish brown", 180),
    p("32607", [wx + 1, 27, 3], "lime", 0)
  );
}

// Forward Nose Prow & Dual-Stepped 928 Cockpit (Z: -22..-7, Y: 22..30)
// Sculpted redwood nose tip with Classic Space front directional thrusters
s2Ops.push(
  p("3298", [-2, 22, -21], "reddish brown", 0),
  p("3298", [0, 22, -21], "reddish brown", 0),
  p("11477", [-3, 22, -20], "dark tan", 0),
  p("11477", [2, 22, -20], "dark tan", 0),
  p("4599b", [-2, 22, -22], "pearl gold", 0),
  p("4599b", [1, 22, -22], "pearl gold", 0),
  p("4589", [-1, 22, -22], "trans yellow", 0),
  p("4589", [0, 22, -22], "trans yellow", 0),
  p("85984", [-1, 25, -19], "yellow", 0),
  p("2412b", [-1, 25, -18], "black", 0)
);

// Cockpit Side Cheeks & Interior Ewok Astronaut Stations (Z: -17..-8)
s2Ops.push(
  // Pilot & Co-Pilot Seats + Classic Space Steering Stands
  p("4079", [-1, 22, -14], "yellow", 0),
  p("3829c01", [-1, 22, -16], "light bluish grey", 0),
  p("4079", [-1, 24, -10], "tan", 0),
  p("85984", [-1, 24, -12], "yellow", 0),
  // Left & Right timber hull cheeks framing the stepped canopies
  box({ at: [-4, 22, -17], size: [1, 4, 9], colour: "reddish brown", texture: "log" }),
  box({ at: [3, 22, -17], size: [1, 4, 9], colour: "reddish brown", texture: "log" }),
  p("11477", [-5, 22, -16], "dark tan", 90),
  p("11477", [3, 22, -16], "dark tan", 270),
  p("11477", [-5, 22, -13], "reddish brown", 90),
  p("11477", [3, 22, -13], "reddish brown", 270),
  p("11477", [-5, 22, -10], "dark tan", 90),
  p("11477", [3, 22, -10], "dark tan", 270),
  // Iconic 1979 Set 928 Dual Stepped Trans-Yellow 3939 Windscreens!
  p("3939", [-3, 25, -17], "trans yellow", 0),
  p("3939", [-3, 28, -13], "trans yellow", 0),
  // Side amber observation slopes & timber roof arch behind canopy
  p("3040b", [-4, 26, -13], "trans yellow", 90),
  p("3040b", [3, 26, -13], "trans yellow", 270),
  p("3040b", [-4, 26, -10], "trans yellow", 90),
  p("3040b", [3, 26, -10], "trans yellow", 270),
  p("3307", [-3, 26, -8], "reddish brown", 0)
);

// Rear Fuselage Cargo Bay, Thatch Dorsal Spine & Lowering Plank Ramp (Z: -8..12, Y: 22..38)
s2Ops.push(
  // Left & Right Cargo Bay Log Walls
  box({ at: [-5, 22, -7], size: [1, 7, 16], colour: "reddish brown", texture: "log" }),
  box({ at: [4, 22, -7], size: [1, 7, 16], colour: "reddish brown", texture: "log" }),
  // Sloped timber fairing along cargo bay sides
  ...[-6, -3, 0, 3, 6].flatMap((z, i) => [
    p("3298", [-7, 22, z], i % 2 === 0 ? "tan" : "reddish brown", 90),
    p("3298", [4, 22, z], i % 2 === 0 ? "tan" : "reddish brown", 270),
    p("54200", [-5, 29, z], "dark tan", 90),
    p("54200", [4, 29, z], "dark tan", 270),
    p("32607", [-5, 29, z + 1], "green", 0),
    p("32607", [4, 29, z + 1], "green", 0)
  ]),
  // Cargo Bay Roof Deck (Z: -7..6, Y: 29..31)
  floor({ at: [-4, 29, -7], size: [8, 13], layers: 2, colour: "tan", top: "tile" }),
  // Thatch & Timber Dorsal Ridge Spine (Y: 31..34)
  ...[-6, -4, -2, 0, 2, 4].flatMap((z) => [
    p("3039", [-3, 31, z], "reddish brown", 90),
    p("3039", [1, 31, z], "reddish brown", 270),
    p("3069b", [-1, 33, z], "yellow", 0),
    p("32607", [-1, 33, z + 1], "green", 0)
  ]),
  // Dorsal Rotating Classic Space Amber Radar Mast (Y: 31..40 at Z: -2..0)
  p("3940b", [-1, 34, -2], "reddish brown", 0),
  p("35394", [-2, 40, -3], "trans yellow", 0),
  p("4740", [-1, 42, -2], "reddish brown", 0),
  p("4589", [-1, 43, -2], "trans red", 0)
);

// Twin Vertical Carved-Totem Tail Fins (X: -8 and X: 6, Z: 2..9, Y: 23..36)
for (const [tx, dishOff] of [[-8, -8], [6, 6]]) {
  s2Ops.push(
    p("3587", [tx, 23, 3], "reddish brown", 0),
