    if (x >= -39 && x <= -18 && (z <= -8 || z >= 8)) {
      detailOps.push(
        p((x + z) % 4 === 0 ? "32607" : "24866", [x, 2, z], (x + z) % 6 === 0 ? "yellow" : "green", 0)
      );
    }
    // Around Launch Pad base
