      );
    }
  }
}

// High Canopy Crown Leaf & Blossom Clusters on Command Tree (Y: 68..71) & Gantry Tree (Y: 66..69)
for (let x = -37; x <= -20; x += 1) {
  for (let z = -9; z <= 8; z += 2) {
    detailOps.push(
      p((x + z) % 3 === 0 ? "24866" : "32607", [x, 68, z], (x % 2 === 0) ? "green" : "lime", 0),
      p("54200", [x, 69, z + 1], (z % 4 === 0) ? "yellow" : "dark green", (x * 90) & 270)
    );
  }
}
for (let x = 27; x <= 38; x += 1) {
  for (let z = -7; z <= 6; z += 2) {
    detailOps.push(
      p("32607", [x, 66, z], (x % 2 === 0) ? "green" : "lime", 0),
