});

// Nominal footprint lookup [xStuds, stackingPlates, zStuds] at turn 0 for 100% overlap-free placement
const PART_DIMS = {
  "3005": [1, 3, 1], "3004": [2, 3, 1], "3622": [3, 3, 1], "3010": [4, 3, 1],
  "3009": [6, 3, 1], "3008": [8, 3, 1], "3003": [2, 3, 2], "3002": [3, 3, 2],
  "3001": [4, 3, 2], "2456": [6, 3, 2], "98283": [2, 3, 1], "30136": [2, 3, 1],
  "2877": [2, 3, 1], "3024": [1, 1, 1], "3023b": [2, 1, 1], "3623": [3, 1, 1],
  "3710": [4, 1, 1], "3666": [6, 1, 1], "3460": [8, 1, 1], "3022": [2, 1, 2],
  "3021": [3, 1, 2], "3020": [4, 1, 2], "3795": [6, 1, 2], "3034": [8, 1, 2],
  "3031": [4, 1, 4], "3032": [6, 1, 4], "51739": [4, 1, 3], "41769a": [2, 1, 4],
  "41770a": [2, 1, 4], "43722a": [2, 1, 3], "43723a": [2, 1, 3], "3070b": [1, 1, 1],
  "3069b": [2, 1, 1], "63864": [3, 1, 1], "2431": [4, 1, 1], "6636": [6, 1, 1],
  "3068b": [2, 1, 2], "87079": [4, 1, 2], "2412b": [2, 1, 1], "54200": [1, 2, 1],
  "85984": [2, 2, 1], "3040b": [1, 3, 2], "3039": [2, 3, 2], "3038": [3, 3, 2],
  "3037": [4, 3, 2], "3665a": [1, 3, 2], "3660b": [2, 3, 2], "3298": [2, 3, 3],
  "3747b": [2, 3, 3], "11477": [1, 3, 2], "15068": [2, 3, 2], "50950": [1, 3, 3],
  "61678": [1, 3, 4], "3062b": [1, 3, 1], "3941": [2, 3, 2], "87081": [4, 3, 4],
