  "3960": [4, 2, 4], "35394": [4, 2, 4], "3961": [8, 3, 8], "50990b": [12, 3, 12],
  "3957a": [1, 12, 1], "4599b": [1, 3, 1], "2489": [2, 5, 2], "4424": [4, 6, 4],
  "3939": [6, 3, 3], "2437": [4, 4, 3], "6238a": [4, 3, 4], "4079": [2, 6, 2],
  "3829c01": [2, 6, 1], "4600": [4, 5, 2], "4345b": [2, 6, 3], "4588": [2, 3, 2],
  "3940b": [2, 6, 2], "2340": [1, 9, 5], "3587": [2, 11, 5], "30385": [1, 5, 1],
  "30176": [1, 3, 1], "32607": [1, 1, 1], "24866": [1, 1, 1], "2423": [3, 1, 4],
  "2417": [5, 1, 6], "2435": [3, 12, 3], "3470": [4, 18, 4], "3659": [4, 3, 1],
  "6182": [4, 6, 1], "3307": [6, 6, 1]
};

const occupied = new Set();
const key = (x, y, z) => `${x},${y},${z}`;

function reserveBox(x, y, z, w, h, d, pad = 0) {
  for (let ix = x - pad; ix < x + w + pad; ix++) {
    for (let iy = y; iy < y + h; iy++) {
      for (let iz = z - pad; iz < z + d + pad; iz++) {
        occupied.add(key(ix, iy, iz));
      }
    }
  }
}

function p(part, at, colour, turn = 0, extra = {}) {
  const dims = PART_DIMS[part] || [2, 3, 2];
  const [x, y, z] = at;
  const w = (turn === 90 || turn === 270) ? dims[2] : dims[0];
  const h = dims[1];
  const d = (turn === 90 || turn === 270) ? dims[0] : dims[2];
  // Extra reach padding for foliage/trees
  const pad = (part === "3470" || part === "2435") ? 1 : 0;
  for (let ix = x - pad; ix < x + w + pad; ix++) {
    for (let iy = y; iy < y + h; iy++) {
      for (let iz = z - pad; iz < z + d + pad; iz++) {
        if (occupied.has(key(ix, iy, iz))) return null;
      }
    }
  }
  reserveBox(x, y, z, w, h, d, pad);
  return place({ part, at: [x, y, z], colour, turn, ...extra });
}

// Helper for a glowing Ewok Amber-Sap Space Beacon (barrel + sap cone + radar dish)
function sapBeacon(x, y, z) {
  return [
    p("2489", [x, y, z], "reddish brown"),
    p("4740", [x, y + 5, z], "trans yellow"),
    p("4589", [x, y + 6, z], "trans red"),
    p("4589", [x + 1, y + 6, z + 1], "trans yellow"),
