// Sculpted Wing Leading Edges using Wedge Plates, Curved Slopes & Planking Tiles at Y: 22
// Left (-X) & Right (+X) stepped delta wing leading edges
const wingSteps = [
  { lx: -5, rx: 3, z: -17, lPart: "43723a", rPart: "43722a", col: "reddish brown" },
  { lx: -7, rx: 5, z: -13, lPart: "41770a", rPart: "41769a", col: "reddish brown" },
