// Forward Nose Prow & Dual-Stepped 928 Cockpit (Z: -22..-7, Y: 22..30)
// Sculpted redwood nose tip with Classic Space front directional thrusters
s2Ops.push(
  p("3298", [-2, 22, -21], "reddish brown", 0),
