}

// Helper for gnarled redwood root spurs gripping the forest floor
function rootSpur(x, z, dirX, dirZ, steps = 5) {
  const ops = [];
  for (let i = 0; i < steps; i++) {
    const rx = x + dirX * i;
    const rz = z + dirZ * i;
    const h = Math.max(2, (steps - i) * 2);
    ops.push(
      box({
        at: [rx, 0, rz],
        size: [2, h, 2],
        colour: i % 2 === 0 ? "reddish brown" : "dark tan",
        interior: "solid"
      })
    );
    const turn = dirZ < 0 ? 0 : dirZ > 0 ? 180 : dirX < 0 ? 90 : 270;
    ops.push(p("11477", [rx, h, rz], i % 2 === 0 ? "reddish brown" : "dark brown", turn));
    if (i === steps - 1) {
      ops.push(p("32607", [rx, h, rz + (dirZ === 0 ? 1 : 0)], "green"));
      ops.push(p("24866", [rx + (dirX === 0 ? 1 : 0), h, rz], "yellow"));
    }
  }
  return ops;
}

